-- ============================================================
-- 05_seed_planning.sql — budgets + savings goals. Re-runnable.
--   mysql --login-path=finance finance_db < sql/05_seed_planning.sql
--
-- 13 budgeted categories x 18 months = 234 rows, generated by a
-- recursive CTE walking the month axis rather than hand-typed.
-- Budget values are Satayu Dhal's (BUILD_PLAN.md Phase 4) and are edited in
-- the plan CTE below, in one place, not in 234 INSERTs.
-- ============================================================
USE finance_db;

TRUNCATE TABLE budgets;
TRUNCATE TABLE savings_goals;

-- ------------------------------------------------------------
-- Budgets.
--
-- The month axis is derived from the data rather than hardcoded, so
-- loading a longer statement history in Phase 9 extends the budget
-- automatically instead of silently leaving new months unbudgeted
-- (which would read as a 100% favourable variance).
--
-- months: anchor on the first month that has transactions, then add
-- one month per recursion until the last. 18 iterations, far inside
-- the default cte_max_recursion_depth of 1000.
--
-- The CROSS JOIN against plan is what turns 18 months x 13 categories
-- into the 234 rows; the JOIN to categories resolves the name and
-- drops anything misspelled -- which the 234-row test then catches.
-- ------------------------------------------------------------
INSERT INTO budgets (category_id, budget_month, budget_amount)
WITH RECURSIVE
bounds AS (
  SELECT CAST(DATE_FORMAT(MIN(txn_date), '%Y-%m-01') AS DATE) AS first_month,
         CAST(DATE_FORMAT(MAX(txn_date), '%Y-%m-01') AS DATE) AS last_month
  FROM transactions
),
months AS (
  SELECT first_month AS budget_month, last_month FROM bounds
  UNION ALL
  SELECT budget_month + INTERVAL 1 MONTH, last_month
  FROM months
  WHERE budget_month < last_month
),
plan (category_name, budget_amount) AS (
  SELECT 'Rent',                 6500 UNION ALL
  SELECT 'Groceries',            4000 UNION ALL
  SELECT 'Utilities & Recharge', 1300 UNION ALL
  SELECT 'Transport',            1800 UNION ALL
  SELECT 'Food Delivery',        4000 UNION ALL
  SELECT 'Dining Out',           1200 UNION ALL
  SELECT 'Snacks & Tea',          800 UNION ALL
  SELECT 'Shopping',             3000 UNION ALL
  SELECT 'Subscriptions',         400 UNION ALL
  SELECT 'Entertainment',         300 UNION ALL
  SELECT 'Software & Tools',     1500 UNION ALL
  SELECT 'Education',            1000 UNION ALL
  SELECT 'Health',                200
)
SELECT c.category_id, m.budget_month, p.budget_amount
FROM months m
CROSS JOIN plan p
JOIN categories c ON c.category_name = p.category_name
ORDER BY m.budget_month, c.category_id;

-- ------------------------------------------------------------
-- Savings goals (BUILD_PLAN.md Phase 4 / DATA_INVENTORY C4).
-- saved_amount is left at 0: progress is derived in the analytics
-- layer from actual balances, not stored as a second copy that would
-- drift from the transactions it is supposed to summarize.
-- ------------------------------------------------------------
INSERT INTO savings_goals (goal_name, target_amount, target_date) VALUES
 ('Emergency Fund',          150000, '2027-03-31'),
 ('New Laptop Upgrade Fund',  60000, '2027-06-30');

-- ---------- planning profile ----------
SELECT COUNT(*)                          AS budget_rows,       -- 234
       COUNT(DISTINCT budget_month)      AS months,            -- 18
       COUNT(DISTINCT category_id)       AS categories,        -- 13
       MIN(budget_month)                 AS first_month,
       MAX(budget_month)                 AS last_month,
       SUM(budget_amount)                AS total_budgeted     -- 468000
FROM budgets;

SELECT budget_month, SUM(budget_amount) AS monthly_budget      -- 26000 every month
FROM budgets GROUP BY budget_month ORDER BY budget_month LIMIT 3;

SELECT c.category_name, b.budget_amount, COUNT(*) AS months_budgeted
FROM budgets b JOIN categories c ON c.category_id = b.category_id
GROUP BY c.category_name, b.budget_amount
ORDER BY b.budget_amount DESC, c.category_name;

SELECT goal_name, target_amount, target_date,
       TIMESTAMPDIFF(MONTH, CURDATE(), target_date) AS months_remaining
FROM savings_goals ORDER BY target_date;
